#include <stdio.h>
#include <string.h>
int main(void) {
    char s[20] = "Kath";
    char t[] = "mandu";
    int n = strlen(s), i = 0;
    while ((s[n + i] = t[i]) != '\0')
        i++;
    printf("%s %zu %d", s, strlen(s), strcmp(s, "Kathmandu") == 0);
    return 0;
}

