What is the output of the following program?

#include <stdio.h>
void modify(int a[], int n) {
    for (int i = 0; i < n; i++)
        a[i] += i;
    n = 0;
}
int main(void) {
    int x[4] = {10, 20, 30, 40}, n = 4;
    modify(x, n);
    printf("%d %d %d", x[1], x[3], n);
    return 0;
}

