What is the output of the following program?

#include <stdio.h>
int maxIndex(const int a[], int n) {
    int k = 0;
    for (int i = 1; i < n; i++)
        if (a[i] >= a[k])
            k = i;
    return k;
}
int main(void) {
    int v[6] = {4, 9, 2, 9, 7, 1};
    printf("%d", maxIndex(v, 6));
    return 0;
}

What is the output of the following program?

#include <stdio.h>
int sum(const int *p, int n) {
    int s = 0;
    for (int i = 0; i < n; i++)
        s += p[i];
    return s;
}
int main(void) {
    int m[2][3] = {{1, 2, 3}, {4, 5, 6}};
    printf("%d", sum(m[1], 3));
    return 0;
}

